<script>
  // Hero Carousel
  const heroTrack = document.getElementById('heroTrack');
  const heroDots = document.getElementById('heroDots');
  const totalSlides = 5;
  let currentSlide = 0;
  let heroTimer;

  function buildDots() {
    for (let i = 0; i < totalSlides; i++) {
      const btn = document.createElement('button');
      btn.className = 'hero-dot' + (i === 0 ? ' active' : '');
      btn.setAttribute('aria-label', 'Go to slide ' + (i+1));
      btn.addEventListener('click', () => goToSlide(i));
      heroDots.appendChild(btn);
    }
  }

  function goToSlide(n) {
    currentSlide = (n + totalSlides) % totalSlides;
    heroTrack.style.transform = `translateX(-${currentSlide * 100}%)`;
    document.querySelectorAll('.hero-dot').forEach((d, i) => d.classList.toggle('active', i === currentSlide));
    resetTimer();
  }

  function resetTimer() {
    clearInterval(heroTimer);
    heroTimer = setInterval(() => goToSlide(currentSlide + 1), 5000);
  }

  document.getElementById('heroPrev').addEventListener('click', () => goToSlide(currentSlide - 1));
  document.getElementById('heroNext').addEventListener('click', () => goToSlide(currentSlide + 1));
  buildDots();
  resetTimer();

  // New Courses Carousel
  const newTrack = document.getElementById('newCoursesTrack');
  const cardWidth = 280;
  let newOffset = 0;

  function getMaxNewOffset() {
    const wrapper = document.getElementById('newCoursesWrapper');
    const totalW = newTrack.scrollWidth;
    return Math.max(0, totalW - wrapper.offsetWidth);
  }

  document.getElementById('newPrev').addEventListener('click', () => {
    newOffset = Math.max(0, newOffset - cardWidth);
    newTrack.style.transform = `translateX(-${newOffset}px)`;
  });
  document.getElementById('newNext').addEventListener('click', () => {
    newOffset = Math.min(getMaxNewOffset(), newOffset + cardWidth);
    newTrack.style.transform = `translateX(-${newOffset}px)`;
  });

  // Countdown Timer
  let timeLeft = 2 * 3600 + 34 * 60 + 17;
  function updateCountdown() {
    if (timeLeft <= 0) return;
    timeLeft--;
    const h = String(Math.floor(timeLeft / 3600)).padStart(2, '0');
    const m = String(Math.floor((timeLeft % 3600) / 60)).padStart(2, '0');
    const s = String(timeLeft % 60).padStart(2, '0');
    const el = document.getElementById('countdownTimer');
    if (el) el.textContent = `${h}:${m}:${s}`;
  }
  setInterval(updateCountdown, 1000);
</script>
