/* shared.css — CreativeHub Design System */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --red: #F02D00;
  --dark: #171717;
  --white: #ffffff;
  --gray-50: #f8f8f8;
  --gray-100: #f0f0f0;
  --gray-200: #e0e0e0;
  --gray-400: #999;
  --gray-600: #555;
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 16px;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 15px;
  color: var(--dark);
  background: #fff;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
img { display: block; max-width: 100%; }
button { font-family: inherit; cursor: pointer; }

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-pad {
  padding: 72px 0;
}

/* Promo Banner */
.promo-banner {
  background: var(--dark);
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px 48px 10px 16px;
  font-size: 14px;
  position: relative;
  z-index: 100;
}
.promo-banner-inner {
  display: flex;
  align-items: center;
  gap: 16px;
}
.promo-text { font-weight: 500; }
.countdown-timer {
  font-weight: 800;
  color: var(--red);
  font-variant-numeric: tabular-nums;
  font-size: 15px;
  letter-spacing: 0.05em;
}
.promo-close {
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: rgba(255,255,255,0.6);
  font-size: 16px;
  line-height: 1;
  padding: 4px;
  transition: color 0.2s;
}
.promo-close:hover { color: #fff; }

/* Header */
.site-header {
  background: #fff;
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 200;
  box-shadow: 0 1px 8px rgba(0,0,0,0.06);
}
.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 28px;
}
.site-logo {
  font-size: 22px;
  font-weight: 900;
  color: var(--dark);
  text-decoration: none;
  white-space: nowrap;
  flex-shrink: 0;
}
.site-logo span { color: var(--red); }

.site-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}
.nav-link {
  font-size: 14px;
  font-weight: 500;
  color: var(--dark);
  text-decoration: none;
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  transition: background 0.15s, color 0.15s;
}
.nav-link:hover { background: var(--gray-100); }
.nav-link.active { color: var(--red); }
.nav-plus { color: var(--red); font-weight: 700; }

.header-search {
  flex: 1;
  position: relative;
  max-width: 360px;
}
.search-input {
  width: 100%;
  height: 38px;
  border: 1.5px solid var(--gray-200);
  border-radius: 20px;
  padding: 0 40px 0 16px;
  font-size: 14px;
  font-family: inherit;
  background: var(--gray-50);
  transition: border-color 0.2s, background 0.2s;
  outline: none;
}
.search-input:focus {
  border-color: var(--dark);
  background: #fff;
}
.search-icon {
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 16px;
  pointer-events: none;
  color: var(--gray-400);
}
.header-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 22px;
  color: var(--dark);
  padding: 4px;
  margin-left: auto;
}
.mobile-nav {
  display: none;
  flex-direction: column;
  padding: 12px 24px 16px;
  border-top: 1px solid var(--gray-200);
  gap: 4px;
}
.mobile-nav.open { display: flex; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-family: inherit;
  font-size: 14px;
  font-weight: 700;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  border: 2px solid transparent;
  text-decoration: none;
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s, transform 0.1s, box-shadow 0.15s;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }
.btn-primary {
  background: var(--red);
  color: #fff;
  border-color: var(--red);
}
.btn-primary:hover {
  background: #d42800;
  border-color: #d42800;
  box-shadow: 0 4px 16px rgba(240,45,0,0.3);
}
.btn-ghost {
  background: transparent;
  color: var(--dark);
  border-color: transparent;
}
.btn-ghost:hover { background: var(--gray-100); }
.btn-outline {
  background: transparent;
  color: var(--dark);
  border-color: var(--dark);
}
.btn-outline:hover { background: var(--dark); color: #fff; }
.btn-outline-white {
  background: transparent;
  color: #fff;
  border-color: rgba(255,255,255,0.4);
}
.btn-outline-white:hover { background: rgba(255,255,255,0.12); }
.btn-lg { font-size: 16px; padding: 14px 32px; }

/* Footer */
.site-footer {
  background: var(--dark);
  color: rgba(255,255,255,0.65);
  padding: 56px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  margin-bottom: 48px;
}
.footer-heading {
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
  background: none;
  border: none;
  color: #fff;
  display: block;
  width: 100%;
  text-align: left;
  cursor: default;
  padding: 0;
}
.footer-links {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.footer-links a {
  font-size: 13px;
  color: rgba(255,255,255,0.55);
  text-decoration: none;
  transition: color 0.15s;
  line-height: 1.4;
}
.footer-links a:hover { color: #fff; }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 28px;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}
.footer-logo {
  font-size: 20px;
  font-weight: 900;
  color: #fff;
}
.footer-logo span { color: var(--red); }
.footer-legal {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-left: auto;
}
.footer-legal a {
  font-size: 12px;
  color: rgba(255,255,255,0.4);
  text-decoration: none;
  transition: color 0.15s;
}
.footer-legal a:hover { color: #fff; }
.footer-langs {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.footer-langs span {
  font-size: 12px;
  color: rgba(255,255,255,0.4);
  cursor: pointer;
  transition: color 0.15s;
}
.footer-langs span:hover { color: #fff; }

/* Responsive */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .header-search { max-width: 240px; }
}

@media (max-width: 768px) {
  .site-nav { display: none; }
  .header-search { display: none; }
  .header-actions { display: none; }
  .mobile-menu-btn { display: flex; }
  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-heading {
    cursor: pointer;
    padding: 14px 0;
    border-bottom: 1px solid rgba(255,255,255,0.1);
    display: flex;
    justify-content: space-between;
    align-items: center;
