<script>
  function filterCategory(el, category) {
    // Update sidebar active state
    document.querySelectorAll('.sidebar-item').forEach(item => item.classList.remove('active'));
    el.classList.add('active');

    // Update chip active state (if called from chip)
    if (el.classList.contains('filter-chip')) {
      document.querySelectorAll('.filter-chip').forEach(c => c.classList.remove('active'));
      el.classList.add('active');
    }

    // Show/hide sections
    const sections = document.querySelectorAll('.category-section');
    if (category === 'all') {
      sections.forEach(s => s.style.display = '');
    } else {
      sections.forEach(s => {
        s.style.display = s.dataset.section === category ? '' : 'none';
      });
    }
  }

  function setChip(el, category) {
    filterCategory(el, category);
    // Also sync sidebar
    const sidebarItem = document.querySelector(`.sidebar-item[data-category="${category}"]`);
    if (sidebarItem) {
      document.querySelectorAll('.sidebar-item').forEach(i => i.classList.remove('active'));
      sidebarItem.classList.add('active');
    }
  }
</script>
