<script>
  // Pricing toggle
  function switchPlan(plan) {
    const yearly = document.getElementById('pricingYearly');
    const monthly = document.getElementById('pricingMonthly');
    const tabY = document.getElementById('tabYearly');
    const tabM = document.getElementById('tabMonthly');

    if (plan === 'yearly') {
      yearly.style.display = '';
      monthly.style.display = 'none';
      tabY.classList.add('active');
      tabM.classList.remove('active');
    } else {
      yearly.style.display = 'none';
      monthly.style.display = '';
      tabY.classList.remove('active');
      tabM.classList.add('active');
    }
  }

  // FAQ accordion
  function toggleFaq(idx) {
    const item = document.getElementById('faq-' + idx);
    const isOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(i => i.classList.remove('open'));
    if (!isOpen) item.classList.add('open');
  }

  // Benefits carousel
  const benefitsTrack = document.getElementById('benefitsTrack');
  let benefitsOffset = 0;
  const benefitCardW = 324;

  function getMaxBenefitsOffset() {
    return Math.max(0, benefitsTrack.scrollWidth - benefitsTrack.parentElement.offsetWidth);
  }

  document.getElementById('benefitsPrev').addEventListener('click', () => {
    benefitsOffset = Math.max(0, benefitsOffset - benefitCardW);
    benefitsTrack.style.transform = `translateX(-${benefitsOffset}px)`;
  });
  document.getElementById('benefitsNext').addEventListener('click', () => {
    benefitsOffset = Math.min(getMaxBenefitsOffset(), benefitsOffset + benefitCardW);
    benefitsTrack.style.transform = `translateX(-${benefitsOffset}px)`;
  });

  // Catalog carousel
  const catalogTrack = document.getElementById('catalogTrack');
  let catalogOffset = 0;
  const catalogCardW = 240;

  function getMaxCatalogOffset() {
    return Math.max(0, catalogTrack.scrollWidth - catalogTrack.parentElement.offsetWidth);
  }

  document.getElementById('catalogPrev').addEventListener('click', () => {
    catalogOffset = Math.max(0, catalogOffset - catalogCardW);
    catalogTrack.style.transform = `translateX(-${catalogOffset}px)`;
  });
  document.getElementById('catalogNext').addEventListener('click', () => {
    catalogOffset = Math.min(getMaxCatalogOffset(), catalogOffset + catalogCardW);
    catalogTrack.style.transform = `translateX(-${catalogOffset}px)`;
  });
</script>
